    merged.ready = { ...base.ready, ...(raw.ready || {}) };
    merged.montage = { ...base.montage, ...(raw.montage || {}) };
    merged.dream = { ...base.dream, ...(raw.dream || {}) };
    merged.quiz = { ...base.quiz, ...(raw.quiz || {}) };
    merged.visited = Array.isArray(raw.visited) ? [...new Set(raw.visited.filter(n => Number.isInteger(n) && n >= 1 && n <= 13))] : [];
    merged.markers = Array.isArray(raw.markers) ? raw.markers.filter(x => ["ingranaggio", "direzione", "linguaggio", "relazione"].includes(x)) : [];
