  menuToggle.addEventListener("click", openMenu); menuClose.addEventListener("click", closeMenu); scrim.addEventListener("click", closeMenu); $$("a", sideNav).forEach(link => link.addEventListener("click", closeMenu));
  sideNav.addEventListener("keydown", event => { if (event.key !== "Tab") return; const list = menuFocusables(), first = list[0], last = list.at(-1); if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } });
  document.addEventListener("keydown", event => { if (event.key === "Escape" && sideNav.classList.contains("open")) closeMenu(); });

  const updateProgress = () => { $("#progressBar").style.width = `${new Set(state.visited).size / 13 * 100}%`; $$(".side-nav a[href^='#s']").forEach((link, i) => link.classList.toggle("visited", state.visited.includes(i + 1))); };
  if ("IntersectionObserver" in window) { const observer = new IntersectionObserver(entries => entries.forEach(entry => { if (!entry.isIntersecting) return; const n = Number(entry.target.dataset.section); if (!state.visited.includes(n)) { state.visited.push(n); state.visited.sort((a, b) => a - b); save(); updateProgress(); } }), { threshold: .2 }); $$('[data-section]').forEach(section => observer.observe(section)); }
