  const renderQuiz = () => { const qs = state.quiz, q = quiz[qs.current], recovery = qs.recovery; $("#masteryCount").textContent = `${qs.mastered.length} / 16 nuclei`; $("#masteryBar").style.width = `${qs.mastered.length / 16 * 100}%`; $("#quizNav").innerHTML = quiz.map((item, i) => `<button type="button" data-q="${i}" class="${i === qs.current ? "current" : ""} ${qs.mastered.includes(i) ? "mastered" : ""}" aria-label="Nucleo ${i + 1}: ${item[0]}${qs.mastered.includes(i) ? ", compreso" : ""}">${i + 1}</button>`).join(""); $$("#quizNav button").forEach(button => button.addEventListener("click", () => { qs.current = Number(button.dataset.q); qs.recovery = false; save(); renderQuiz(); })); const question = recovery ? q[6] : q[1], options = recovery ? q[7] : q[2]; $("#quizCard").innerHTML = `<p class="core-label">Nucleo ${qs.current + 1} · ${q[0]}${recovery ? " · recupero" : ""}</p><h3>${question}</h3><div class="quiz-options">${options.map((option, i) => `<button type="button" data-answer="${i}">${option}</button>`).join("")}</div><div id="quizFeedback" aria-live="polite"></div>`; $$("#quizCard [data-answer]").forEach(button => button.addEventListener("click", () => answerQuiz(Number(button.dataset.answer)))); $("#quizComplete").hidden = qs.mastered.length !== 16; };
